"""An editorial student-life page using the owner's brief and attributed campus photographs."""
import json
from pathlib import Path
from html import escape as esc
from lxml import html as LH
from homepage import ambient

FAIR='https://newsletter.tcu.edu.tw/?p=19322'
JAPAN='https://mdm.tcu.edu.tw/p/406-1021-66149,r8.php?Lang=zh-tw'


def photo(src, alt, caption, cls='', priority=False):
    loading='fetchpriority="high"' if priority else 'loading="lazy"'
    return f'''<figure class="life-figure {cls}"><button class="life-photo-button" type="button" data-gallery-open data-gallery-caption="{esc(caption)}" aria-label="View photo: {esc(caption)}"><img src="{src}" alt="{esc(alt)}" {loading} decoding="async"><span class="life-photo-action">View photo</span></button><figcaption>{esc(caption)}</figcaption></figure>'''


PROJECTS=[
 {'id':'presentations','label':'Presentations','title':'Find your voice in front of a room.','body':'Frequent class presentations build confidence and clear speaking. Preparing together also means organising research, dividing the work, and explaining an idea when others ask questions.','image':'assets/photos/cafe-project.webp','alt':'Students from the department’s Indonesian cohort presenting a project','caption':'Student project presentation · Indonesian cohort · Department photo archive'},
 {'id':'podcast','label':'Podcast','title':'Turn a topic into a programme.','body':'Podcast projects bring communication and marketing into the same assignment: choosing a subject, shaping a message, and presenting it for an audience. The department publishes a student podcast-branding collection.','image':'assets/photos/digital-learning.webp','alt':'Students learning with computers in a classroom','caption':'Digital-learning classroom · Department photo archive'},
 {'id':'final','label':'Final project','title':'Bring your learning together.','body':'The final project (zhuanti) is a chance to develop an idea, work as a team, and present a considered result. It draws on the planning, research, and communication practised throughout the degree.','image':'assets/photos/design-workshop.webp','alt':'Students sharing ideas in a design-thinking workshop','caption':'Design-thinking workshop · Department archive'},
]


def render_life(old_body):
    collection=json.loads((Path(__file__).parent/'content/japan-photo-selection.json').read_text(encoding='utf-8'))
    selected=collection['photos']
    campus=collection['additional_campus_photos']
    def campus_photo(slot,cls,priority=False):
        p=campus[slot]
        return photo(p['path'],p['alt'],p['caption'],cls,priority).replace('<img ',f'<img width="{p["width"]}" height="{p["height"]}" ')
    def japan_photo(slot,cls):
        p=selected[slot]
        return photo(p['path'],p['alt'],p['caption'],cls).replace('<img ',f'<img width="{p["width"]}" height="{p["height"]}" ')
    old=LH.fragment_fromstring(old_body,create_parent='div')
    dialog=old.xpath('.//dialog[@id="photo-dialog"]')
    gallery=LH.tostring(dialog[0],encoding='unicode',method='html') if dialog else ''
    first=PROJECTS[0]
    project_json=json.dumps(PROJECTS,ensure_ascii=False).replace('</','<\\/')
    hero=f'''<section class="wrap life-intro" aria-labelledby="life-page-title"><div class="life-intro-copy"><div class="kicker">Student life · Hualien, Taiwan</div><h1 id="life-page-title" data-editorial-reveal>Life at BMD.</h1><p>Accounting, management, sustainability—and plenty of chances to put them into practice. Student life here includes presentations, creative projects, internships, and working with others.</p><nav class="life-page-index" aria-label="On this page"><a href="#life-learning">Learning</a><a href="#life-projects">Student projects</a><a href="#life-international">Overseas internships</a><a href="#life-community">Volunteering</a></nav></div><div class="life-cover-collage">{campus_photo('yide','life-cover-main',True)}{campus_photo('hospital-building','life-cover-side')}</div></section>'''
    learning='''<section class="wrap life-learning" id="life-learning"><div><div class="kicker">In the classroom</div><h2>Learning how<br>organisations work.</h2><p>Good management involves money, time, and people. Classes give students a foundation; working together gives those ideas a practical setting.</p><a class="text-link" href="academics.html">Learning directions</a></div><dl class="life-course-list"><div><dt>Accounting & financial thinking</dt><dd>Understand costs, plan a budget, and make sense of financial decisions.</dd></div><div><dt>Management & leadership</dt><dd>Manage time, coordinate a team, and understand how companies and organisations operate.</dd></div><div><dt>Sustainability & NPOs</dt><dd>Consider social and environmental responsibility alongside business and non-profit organisation management.</dd></div></dl></section>'''
    projects=f'''<section class="life-project-section" id="life-projects" aria-labelledby="life-project-heading"><div class="wrap"><div class="life-section-heading"><div><div class="kicker">Made by students</div><h2 id="life-project-heading">Projects with an audience.</h2></div></div><div class="life-project-tabs" role="tablist" aria-label="Student project types">{''.join('<button type="button" role="tab" id="life-tab-'+p['id']+'" aria-controls="life-project-panel" aria-selected="'+str(i==0).lower()+'" tabindex="'+('0' if i==0 else '-1')+'" data-life-project="'+str(i)+'">'+p['label']+'</button>' for i,p in enumerate(PROJECTS))}</div><div class="life-project-panel" id="life-project-panel" role="tabpanel" aria-labelledby="life-tab-presentations" tabindex="0"><figure class="life-figure life-project-photo"><button type="button" class="life-photo-button" data-gallery-open data-gallery-caption="{esc(first['caption'])}" aria-label="View photo: {esc(first['caption'])}"><img id="life-project-image" src="{first['image']}" alt="{esc(first['alt'])}" loading="lazy" decoding="async"><span class="life-photo-action">View photo</span></button><figcaption id="life-project-caption">{esc(first['caption'])}</figcaption></figure><div class="life-project-copy"><span class="life-project-subject" id="life-project-subject">{first['label']}</span><h3 id="life-project-title">{first['title']}</h3><p id="life-project-description">{first['body']}</p></div></div></div><script type="application/json" id="life-project-data">{project_json}</script></section>'''
    international=f'''<section class="wrap life-international" id="life-international"><div class="life-abroad-photos">{japan_photo('life-main','life-abroad-main')}{japan_photo('life-prep','life-abroad-detail')}</div><div class="life-abroad-copy"><div class="kicker">Workplace experience</div><h2>Here,<br>and further afield.</h2><p>Internships give students time in a real working environment. Overseas experiences add cross-cultural communication, independence, and a new perspective on the people an organisation serves.</p><ul class="life-destinations" aria-label="Overseas destinations"><li>Japan</li><li>United States</li><li>Thailand</li></ul><p class="life-availability">Destinations and placements vary by year. Confirm current opportunities with the department.</p><a class="text-link" href="exchange.html">International learning</a><a class="life-photo-source" href="{JAPAN}" target="_blank" rel="noopener">Japan service-learning report</a></div></section>'''
    community=f'''<section class="life-community motion-region" id="life-community" data-ambient-surface aria-labelledby="life-community-heading">{ambient('breeze')}<div class="wrap life-community-layout"><div class="life-community-copy"><div class="kicker">Humanistic learning · Service</div><h2 id="life-community-heading">Selling for a cause.</h2><p>Humanistic education and NPO classes connect business skills with care for others. At the 2025 Myanmar-relief fair, food stalls and a BMD student-run photo booth turned teamwork and small-business planning into support for earthquake relief.</p><div class="life-event-line"><time datetime="2025-05-22">22–23 May 2025</time><span>Jianguo & Central campuses</span></div><a class="text-link" href="{FAIR}" target="_blank" rel="noopener">Read the campus report</a><div class="life-volunteer-examples"><h3>Ways to take part</h3><ul><li><b>Plan a charity stall.</b> Budget ingredients, set prices, and record income.</li><li><b>Help run a service activity.</b> Coordinate roles, supplies, and timing.</li><li><b>Support an NPO campaign.</b> Communicate its purpose and keep donors informed.</li></ul></div></div><div class="life-service-collage">{photo('assets/life/charity-stalls.webp','Students serving visitors at fundraising food stalls','Food stalls · Myanmar-relief fair, 2025','life-service-main')}{photo('assets/life/fair-team.webp','Students working together at the fundraising fair','Teamwork at the fair · TCU Newsletter','life-service-detail')}{photo('assets/life/food-fundraiser.webp','Students with food prepared for the Myanmar-relief fundraiser','Student food stall · TCU Newsletter','life-service-small')}</div></div><button type="button" class="ambient-control" aria-pressed="false" aria-label="Pause background motion">Pause background motion</button></section>'''
    end='''<section class="wrap life-next life-next-pair"><a href="internships.html"><span>Before your internship</span><b>Forms & preparation</b></a><a href="contact.html"><span>Questions about taking part?</span><b>Contact the department</b></a></section><div class="wrap life-source-notes"><details><summary>Photos & original department resources</summary><p>Photographs are from the department archive and official TCU reports. Fair photographs: 李家萓 / TCU Newsletter.</p><a href="source-6ec97970ff59.html">All original Student Life activities</a><a href="source-08f4bceb3eb0.html">Virtual Corporation resource</a><a href="https://mdm.tcu.edu.tw/p/412-1021-3692.php?Lang=zh-tw" target="_blank" rel="noopener">Student podcast-branding collection</a></details></div>'''
    end=end.replace('</details></div>','<p>Japan internship photographs: participant-provided collection (2026).</p><p>Additional campus photographs: participant-provided collection.</p></details></div>')
    return '<div class="bmd-life">'+hero+learning+projects+international+community+end+'</div>'+gallery
